-- Synthetic loopback fixtures only; run after all expansion migrations and
-- commerce_rls_checkout.sql (which defines commerce_test assertion helpers).
begin;
select commerce_test.check_true(current_database()='commerce_test' and inet_server_addr() in ('127.0.0.1'::inet,'::1'::inet),'growth fixtures require isolated loopback commerce_test');
insert into auth.users(id,email,email_confirmed_at) values
 ('11000000-0000-4000-8000-000000000001','growth-owner@example.test',now()),
 ('11000000-0000-4000-8000-000000000002','growth-buyer@example.test',now()),
 ('11000000-0000-4000-8000-000000000003','growth-other@example.test',now());
insert into public.commerce_websites(id,slug,name,status) values ('21000000-0000-4000-8000-000000000001','growth-fixture','Growth Fixture','active');
insert into public.commerce_memberships(website_id,user_id,role) values ('21000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000001','owner');
insert into public.commerce_products(id,website_id,name,slug,price_paise,stock_quantity) values ('41000000-0000-4000-8000-000000000001','21000000-0000-4000-8000-000000000001','Growth Product','growth-product',12345,20);
select commerce_test.check_true(not has_function_privilege('anon','public.commerce_growth_workspace(uuid)','EXECUTE') and not has_function_privilege('anon','public.commerce_growth_owner_action(uuid,text,jsonb)','EXECUTE'),'growth RPCs reject inherited anon execute grants');
select commerce_test.check_true(not has_function_privilege('authenticated','commerce_private.quote_coupon(uuid,uuid,text,bigint,bigint,boolean)','EXECUTE'),'coupon quote helper remains private');
select commerce_test.check_true(not has_function_privilege('authenticated','public.commerce_notification_claim(integer,integer)','EXECUTE') and has_function_privilege('service_role','public.commerce_notification_claim(integer,integer)','EXECUTE'),'notification claims service only');
select commerce_test.check_true(not has_table_privilege('authenticated','public.commerce_notification_outbox','SELECT'),'outbox recipient/lease metadata cannot be queried by customers or owners');
set local role authenticated;
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000001',true);
select commerce_test.record('growth_fixed',public.commerce_growth_owner_action('21000000-0000-4000-8000-000000000001','save_coupon','{"code":"fixed50","kind":"fixed","discount_value":5000,"maximum_discount_paise":4000,"minimum_subtotal_paise":10000,"usage_limit":2,"per_customer_limit":1}'));
select commerce_test.record('growth_percentage',public.commerce_growth_owner_action('21000000-0000-4000-8000-000000000001','save_coupon','{"code":"PERCENT","kind":"percentage","discount_value":3333,"minimum_subtotal_paise":0,"per_customer_limit":1}'));
select commerce_test.must_fail($q$select public.commerce_growth_owner_action('21000000-0000-4000-8000-000000000001','save_coupon','{"code":"BADVAL","kind":"fixed","discount_value":1.5,"minimum_subtotal_paise":0,"per_customer_limit":1}')$q$,'SQL rejects fractional coupon paise',array['22023']);
select commerce_test.must_fail($q$select public.commerce_growth_owner_action('21000000-0000-4000-8000-000000000001','save_coupon','{"code":"TAMPER","kind":"fixed","discount_value":500,"minimum_subtotal_paise":0,"per_customer_limit":1,"user_id":"11000000-0000-4000-8000-000000000002"}')$q$,'SQL rejects forged coupon identity',array['22023']);
select commerce_test.must_fail($q$select public.commerce_growth_owner_action('21000000-0000-4000-8000-000000000001','save_coupon','{"code":"BADDATE","kind":"fixed","discount_value":500,"minimum_subtotal_paise":0,"per_customer_limit":1,"starts_at":"2026-11-04T00:00:00Z","ends_at":"2026-11-03T00:00:00Z"}')$q$,'SQL rejects reversed coupon date windows',array['23514']);
select commerce_test.must_fail($q$insert into public.commerce_coupons(website_id,code,kind,discount_value) values('21000000-0000-4000-8000-000000000001','DIRECT','fixed',500)$q$,'owners cannot directly mutate coupon storage',array['42501']);
select commerce_test.check_true((public.commerce_growth_workspace('21000000-0000-4000-8000-000000000001')->'coupons'->0->>'code') is not null,'authorized owner reads private coupons');
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000003',true);
select commerce_test.check_true((select count(*)=0 from public.commerce_coupons),'nonmember coupon RLS returns no rows');
select commerce_test.must_fail($q$select public.commerce_growth_workspace('21000000-0000-4000-8000-000000000001')$q$,'another customer cannot read analytics',array['42501']);
select commerce_test.must_fail($q$select public.commerce_growth_owner_action('21000000-0000-4000-8000-000000000001','archive_coupon',jsonb_build_object('id',(select value->>'id' from commerce_test.state where key='growth_fixed')))$q$,'another customer cannot archive coupon',array['42501']);
reset role;
select commerce_test.check_true((commerce_private.quote_coupon('21000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000002','percent',12345,500,false)->>'discount_paise')::bigint=4114,'percentage discounts round down once to exact paise');
select commerce_test.check_true((commerce_private.quote_coupon('21000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000002','fixed50',12345,500,false)->>'discount_paise')::bigint=4000,'maximum discount cap applies without discounting delivery');
select commerce_test.check_true((select count(*)=0 from public.commerce_coupon_redemptions where website_id='21000000-0000-4000-8000-000000000001'),'previews never consume coupon usage');
select commerce_test.must_fail($q$select commerce_private.quote_coupon('21000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000002','fixed50',9999,0,false)$q$,'minimum subtotal rejects ineligible quote',array['22023']);
update public.commerce_coupons set starts_at=now()+interval '1 day' where code='PERCENT' and website_id='21000000-0000-4000-8000-000000000001';
select commerce_test.must_fail($q$select commerce_private.quote_coupon('21000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000002','PERCENT',12345,0,false)$q$,'future coupon rejected',array['22023']);
update public.commerce_coupons set starts_at=null,ends_at=now()-interval '1 second' where code='PERCENT' and website_id='21000000-0000-4000-8000-000000000001';
select commerce_test.must_fail($q$select commerce_private.quote_coupon('21000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000002','PERCENT',12345,0,false)$q$,'expired coupon rejected',array['22023']);
update public.commerce_coupons set ends_at=null where code='PERCENT' and website_id='21000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000002',true);
select commerce_test.record('growth_order',public.commerce_create_cod_order_v2('21000000-0000-4000-8000-000000000001','[{"product_id":"41000000-0000-4000-8000-000000000001","quantity":1}]','{"name":"Local Buyer","phone":"9000000000"}','pickup','51000000-0000-4000-8000-000000000001','FIXED50'));
select commerce_test.check_true(((select value->'order'->>'total_paise' from commerce_test.state where key='growth_order')::bigint)=8345,'checkout computes subtotal minus trusted coupon amount');
select commerce_test.check_true((public.commerce_create_cod_order_v2('21000000-0000-4000-8000-000000000001','[{"product_id":"41000000-0000-4000-8000-000000000001","quantity":1}]','{"name":"Local Buyer","phone":"9000000000"}','pickup','51000000-0000-4000-8000-000000000001','FIXED50')->'order'->>'id')=(select value->'order'->>'id' from commerce_test.state where key='growth_order'),'coupon order retry returns same order');
select commerce_test.must_fail($q$select public.commerce_checkout_quote_v2('21000000-0000-4000-8000-000000000001','[{"product_id":"41000000-0000-4000-8000-000000000001","quantity":1}]','{"name":"Local Buyer","phone":"9000000000"}','pickup','FIXED50')$q$,'per-customer use limit prevents another discounted order',array['22023']);
reset role;
select commerce_test.check_true((select count(*)=1 from public.commerce_coupon_redemptions where website_id='21000000-0000-4000-8000-000000000001'),'idempotent checkout records exactly one redemption');
update public.commerce_coupons set usage_limit=1 where code='FIXED50' and website_id='21000000-0000-4000-8000-000000000001';
select commerce_test.must_fail($q$select commerce_private.quote_coupon('21000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000003','FIXED50',12345,0,false)$q$,'overall use limit also blocks a different customer',array['22023']);
update public.commerce_coupons set usage_limit=2 where code='FIXED50' and website_id='21000000-0000-4000-8000-000000000001';
select commerce_test.must_fail($q$insert into public.commerce_coupon_redemptions(website_id,coupon_id,order_id,user_id,discount_paise) values('20000000-0000-4000-8000-000000000002',(select (value->>'id')::uuid from commerce_test.state where key='growth_fixed'),(select (value->'order'->>'id')::uuid from commerce_test.state where key='growth_order'),'11000000-0000-4000-8000-000000000002',4000)$q$,'composite tenant guard rejects cross-website redemption',array['23503']);
select commerce_test.must_fail($q$insert into public.commerce_coupon_redemptions(website_id,coupon_id,order_id,user_id,discount_paise) values('21000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from commerce_test.state where key='growth_fixed'),(select (value->'order'->>'id')::uuid from commerce_test.state where key='growth_order'),'11000000-0000-4000-8000-000000000003',4000)$q$,'redemption guard rejects order customer impersonation',array['23503']);

select commerce_test.must_fail($q$update public.commerce_coupon_redemptions set discount_paise=1 where website_id='21000000-0000-4000-8000-000000000001'$q$,'redemption history cannot be edited',array['42501']);
select commerce_test.check_true((select count(*)=1 from public.commerce_notification_outbox where website_id='21000000-0000-4000-8000-000000000001'),'order creation transaction enqueues exactly one deduplicated event');
update public.commerce_orders set status=status where website_id='21000000-0000-4000-8000-000000000001';
select commerce_test.check_true((select count(*)=1 from public.commerce_notification_outbox where website_id='21000000-0000-4000-8000-000000000001'),'unchanged order status does not enqueue duplicate');
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select commerce_test.record('growth_claim',(select item from jsonb_array_elements(public.commerce_notification_claim(25,120)) item where item->>'website_id'='21000000-0000-4000-8000-000000000001' limit 1));
select commerce_test.check_true((select value->>'recipient_email'='growth-buyer@example.test' and value->>'lease_token' is not null from commerce_test.state where key='growth_claim'),'service-only claim resolves verified recipient and obtains lease');
select commerce_test.check_true(not exists(select 1 from jsonb_array_elements(public.commerce_notification_claim(25,120)) item where item->>'website_id'='21000000-0000-4000-8000-000000000001'),'active lease cannot be claimed twice');
select commerce_test.must_fail($q$select public.commerce_notification_ack((select (value->>'id')::uuid from commerce_test.state where key='growth_claim'),'ffffffff-ffff-4fff-8fff-ffffffffffff',true)$q$,'wrong lease token cannot acknowledge notification',array['23505']);
select public.commerce_notification_ack((select (value->>'id')::uuid from commerce_test.state where key='growth_claim'),(select (value->>'lease_token')::uuid from commerce_test.state where key='growth_claim'),false,'provider_unavailable');
reset role;
select commerce_test.check_true((select status='pending' and attempts=1 and available_at>now() and lease_token is null from public.commerce_notification_outbox where website_id='21000000-0000-4000-8000-000000000001'),'failed send schedules bounded retry and clears lease');
update public.commerce_notification_outbox set available_at=now() where website_id='21000000-0000-4000-8000-000000000001';
set local role service_role;
select commerce_test.record('growth_claim',(select item from jsonb_array_elements(public.commerce_notification_claim(25,120)) item where item->>'website_id'='21000000-0000-4000-8000-000000000001' limit 1));
select public.commerce_notification_ack((select (value->>'id')::uuid from commerce_test.state where key='growth_claim'),(select (value->>'lease_token')::uuid from commerce_test.state where key='growth_claim'),true,'','stub-provider-id');
select commerce_test.must_fail($q$select public.commerce_notification_ack((select (value->>'id')::uuid from commerce_test.state where key='growth_claim'),(select (value->>'lease_token')::uuid from commerce_test.state where key='growth_claim'),true)$q$,'successful event cannot be ACKed twice',array['23505']);
reset role;
select commerce_test.check_true((select status='sent' and attempts=2 and sent_at is not null from public.commerce_notification_outbox where website_id='21000000-0000-4000-8000-000000000001'),'successful retry preserves attempt history');
update public.commerce_orders set status='completed' where website_id='21000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000001',true);
select commerce_test.record('growth_analytics',public.commerce_growth_workspace('21000000-0000-4000-8000-000000000001'));
select commerce_test.check_true((select value->'analytics'->>'placed_order_value_paise'='8345' and value->'analytics'->>'completed_cod_value_paise'='8345' and value->'analytics'->'settled_funds_paise'='null'::jsonb and value->'analytics'->'funds_tracking_available'='false'::jsonb from commerce_test.state where key='growth_analytics'),'analytics distinguishes completed COD order value from unknown settled funds');
reset role;

update public.commerce_notification_outbox set status='processing',attempts=5,lease_token=gen_random_uuid(),lease_expires_at=now()-interval '1 second' where website_id='21000000-0000-4000-8000-000000000001' and event_type='order_completed';
set local role service_role;
select public.commerce_notification_claim(25,120);
reset role;
select commerce_test.check_true((select status='failed' and attempts=5 and lease_token is null from public.commerce_notification_outbox where website_id='21000000-0000-4000-8000-000000000001' and event_type='order_completed'),'expired final lease becomes terminal instead of remaining stuck');
set local role service_role;
select commerce_test.check_true((public.commerce_notification_admin('status')->>'failed')::integer>=1,'Admin status returns only aggregate delivery counters');
reset role;
select commerce_test.check_true((select balance_paise=123456 from public.legacy_preservation_fixture where id=1),'growth preserves legacy wallet fixture');
select commerce_test.check_true((select count(*)=1 and bool_and(schedule='0 0 * * *' and command='existing settlement fixture' and active) from cron.job),'growth preserves existing cron job and creates none');
commit;
